module EmployeeSelector(\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] k,\n    input [31:0] lambda,\n    input [15:0] s_1, s_2, s_3, s_4,\n    input [15:0] p_1, p_2, p_3, p_4,\n    input [15:0] r_1, r_2, r_3, r_4,\n    output reg [63:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] PRECOMPUTE = 2'd1;\n    localparam [1:0] ITERATE = 2'd2;\n    localparam [1:0] DONE_STATE = 2'd3;\n\n    // Internal registers\n    reg [1:0] state;\n    reg [2:0] k_reg;\n    reg [31:0] lambda_reg;\n    reg [15:0] s_reg [0:3];\n    reg [15:0] p_reg [0:3];\n    reg [15:0] r_reg [0:3];\n    reg [63:0] term [0:3];\n    reg [63:0] best_total;\n    reg [3:0] mask_counter;\n    reg valid_reg;\n\n    // Helper: popcount for 4 bits\n    wire [2:0] popcount;\n    assign popcount = mask_counter[0] + mask_counter[1] + mask_counter[2] + mask_counter[3];\n\n    // Helper: validity for current mask\n    always @(*) begin\n        valid_reg = 1'b1;\n        if (mask_counter[0] && (r_reg[0] != 16'd0)) begin\n            if ((r_reg[0] - 16'd1) < 0 || (r_reg[0] - 16'd1) >= 4 || !mask_counter[r_reg[0] - 16'd1])\n                valid_reg = 1'b0;\n        end\n        if (mask_counter[1] && (r_reg[1] != 16'd0)) begin\n            if ((r_reg[1] - 16'd1) < 0 || (r_reg[1] - 16'd1) >= 4 || !mask_counter[r_reg[1] - 16'd1])\n                valid_reg = 1'b0;\n        end\n        if (mask_counter[2] && (r_reg[2] != 16'd0)) begin\n            if ((r_reg[2] - 16'd1) < 0 || (r_reg[2] - 16'd1) >= 4 || !mask_counter[r_reg[2] - 16'd1])\n                valid_reg = 1'b0;\n        end\n        if (mask_counter[3] && (r_reg[3] != 16'd0)) begin\n            if ((r_reg[3] - 16'd1) < 0 || (r_reg[3] - 16'd1) >= 4 || !mask_counter[r_reg[3] - 16'd1])\n                valid_reg = 1'b0;\n        end\n    end\n\n    // Helper: total for current mask\n    wire [63:0] current_total;\n    assign current_total = (mask_counter[0] ? term[0] : 64'd0) +\n                          (mask_counter[1] ? term[1] : 64'd0) +\n                          (mask_counter[2] ? term[2] : 64'd0) +\n                          (mask_counter[3] ? term[3] : 64'd0);\n\n    // Main FSM\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 64'd0;\n            mask_counter <= 4'd0;\n            best_total <= 64'd0;\n            k_reg <= 3'd0;\n            lambda_reg <= 32'd0;\n            s_reg[0] <= 16'd0;\n            s_reg[1] <= 16'd0;\n            s_reg[2] <= 16'd0;\n            s_reg[3] <= 16'd0;\n            p_reg[0] <= 16'd0;\n            p_reg[1] <= 16'd0;\n            p_reg[2] <= 16'd0;\n            p_reg[3] <= 16'd0;\n            r_reg[0] <= 16'd0;\n            r_reg[1] <= 16'd0;\n            r_reg[2] <= 16'd0;\n            r_reg[3] <= 16'd0;\n            term[0] <= 64'd0;\n            term[1] <= 64'd0;\n            term[2] <= 64'd0;\n            term[3] <= 64'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        k_reg <= k;\n                        lambda_reg <= lambda;\n                        s_reg[0] <= s_1;\n                        s_reg[1] <= s_2;\n                        s_reg[2] <= s_3;\n                        s_reg[3] <= s_4;\n                        p_reg[0] <= p_1;\n                        p_reg[1] <= p_2;\n                        p_reg[2] <= p_3;\n                        p_reg[3] <= p_4;\n                        r_reg[0] <= r_1;\n                        r_reg[1] <= r_2;\n                        r_reg[2] <= r_3;\n                        r_reg[3] <= r_4;\n                        state <= PRECOMPUTE;\n                        mask_counter <= 4'd0;\n                        best_total <= 64'h8000000000000000;\n                    end\n                end\n\n                PRECOMPUTE: begin\n                    term[0] <= (p_reg[0] << 16) - (lambda_reg * s_reg[0]);\n                    term[1] <= (p_reg[1] << 16) - (lambda_reg * s_reg[1]);\n                    term[2] <= (p_reg[2] << 16) - (lambda_reg * s_reg[2]);\n                    term[3] <= (p_reg[3] << 16) - (lambda_reg * s_reg[3]);\n                    state <= ITERATE;\n                end\n\n                ITERATE: begin\n                    if (popcount == k_reg && valid_reg) begin\n                        if (current_total > best_total) begin\n                            best_total <= current_total;\n                        end\n                    end\n                    if (mask_counter == 4'd15) begin\n                        state <= DONE_STATE;\n                    end else begin\n                        mask_counter <= mask_counter + 4'd1;\n                    end\n                end\n\n                DONE_STATE: begin\n                    result <= best_total;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule